69	/** userId -> public author tag. Accounts without a tag get the generic label, NEVER the account name. */
70	export async function authorTags(userIds: string[]): Promise<Map<string, string>> {
71	  const ids = [...new Set(userIds)];
72	  const out = new Map<string, string>();
73	  if (!ids.length) return out;
74	  const rows = await cyrusDb.cyrusCreator.findMany({ where: { userId: { in: ids } }, select: { userId: true, username: true } }).catch(() => []);
75	  for (const r of rows) if (r.username) out.set(r.userId, r.username);
76	  for (const id of ids) if (!out.has(id)) out.set(id, UNNAMED_AUTHOR);
77	  return out;
78	}
79	
80	export async function authorTagOf(userId: string): Promise<string> {
81	  return (await authorTags([userId])).get(userId) ?? UNNAMED_AUTHOR;
82	}
83	
84	/** A suggestion that is free right now (never the account name): "maker-4f2a". */
85	export async function suggestUsername(): Promise<string> {
86	  for (let i = 0; i < 5; i++) {
87	    const s = `maker-${randomBytes(2).toString("hex")}`;
88	    if ((await checkAvailability(s, null)).ok) return s;
89	  }
90	  return `maker-${randomBytes(4).toString("hex")}`;
91	}
92	
93	/** Drop-in for `db.user.findMany({select:{id,name}})` on PUBLIC surfaces: `name` is the author tag, never the account name. */
94	export async function authorUsers(userIds: string[]): Promise<{ id: string; name: string }[]> {
95	  const m = await authorTags(userIds);
96	  return [...m].map(([id, name]) => ({ id, name }));
97	}
98	/** Drop-in for `db.user.findUnique({select:{name}})` on public surfaces. */
99	export async function authorUser(userId: string): Promise<{ name: string }> {
100	  return { name: await authorTagOf(userId) };
101	}
