import { bridgeEmailBlocked, bridgeGate, go, grantConsent, hasConsent, limited, notFound } from "@/lib/cyrus-bridge/server";

export const dynamic = "force-dynamic";

/**
 * "Sign in with Nxeon" for cyrus.my (CYRUS_DOMAIN_MODE). Nxeon is the identity provider:
 *   ?client_id=cyrus&redirect_uri=<exact cyrus callback>&state&nonce[&prompt=create]
 * Not signed in -> /login (or the consent + /register path for prompt=create), back here after. Signed in, verified
 * email, consent given -> a 90 s Ed25519 assertion (sub = account id, the caller's nonce, this session's hash) to the
 * EXACT callback. Bad client / redirect_uri -> 400, never a redirect. Impersonation never crosses hosts.
 */
export async function GET(req: Request) {
  const cfg = bridgeGate(req, "nxeon");
  if (!cfg) return notFound();
  const url = new URL(req.url);
  const p = parseAuthorize(url.searchParams, "cyrus", cfg);
  if (!p) return Response.json({ error: "invalid_request" }, { status: 400 });
  if (limited(req, "authorize")) return go(callbackUrl(p, { error: "ratelimited" }));
  if (await impersonating()) return go(callbackUrl(p, { error: "impersonating" }));

  const self = `/sso/cyrus/authorize?${authorizeQuery(p)}`;
  const consentPage = (extra = "") => go(`${cfg.nxeonOrigin}/sso/cyrus/consent?${authorizeQuery(p)}${extra}`);
  const user = await currentUser();
  if (!user) {
    // Sign-up: consent comes first (it explains that a Cyrus account IS a Nxeon account), then /register.
    if (p.prompt === "create" && !(await hasConsent("", p.nonce))) return consentPage();
    const page = p.prompt === "create" ? "/register" : "/login";
    // r44: a partner code carried from cyrus.my becomes Nxeon's own referral cookie, so register() attaches the
    // Creator Partner exactly as for a /partner/<code> click (no-op unless CYRUS_ATTRIBUTION=1)
    return receiveCyrusAttribution(req, p.attr, go(`${cfg.nxeonOrigin}${page}?next=${encodeURIComponent(self)}`));
  }
  if (await bridgeEmailBlocked(user)) return consentPage("&verify=1");
  if (!(await hasConsent(user.id, p.nonce))) return consentPage();
  await grantConsent({ userId: user.id }); // a sign-up's one-handshake grant becomes the account's remembered consent

  const code = mintAssertion({
    typ: "login", iss: cfg.nxeonOrigin, aud: cfg.cyrusOrigin, sub: user.id, nonce: p.nonce, sid: await currentSessionTokenHash(),
  }, privateKeyFor("nxeon"));
  return go(callbackUrl(p, { code }));
}
