export async function SignInView({ mode, sp }: { mode: "login" | "create"; sp: Record<string, string | undefined> }) {
  if (!bridgeConfig().enabled || (await headers()).get(CYRUS_HOST_HEADER) !== "1") notFound();
  // The landing's prompt box submits here (GET ?prompt=): it rides through sign-in AND sign-up as the post-login
  // destination /new?prompt=..., so the typed words arrive in the real new-mod screen.
  const handed = nextForPrompt(sp.prompt);
  const next = handed ?? safeCyrusNext(sp.next);
  const me = await currentUser();
  if (me) {
    // Signed in. Allowed (private-beta tester, or public once launched): straight on. Not allowed: say so honestly
    // instead of sending them to a 404.
    if (await modBuilderUser().catch(() => null)) redirect(next);
    return <BetaClosed email={me.email ?? ""} />;
  }
  const err = bridgeErrorText(sp.error);
  const q = (m?: string) => `/auth/nxeon/start?next=${encodeURIComponent(next)}${m ? `&mode=${m}` : ""}`;
  const google = cyrusGoogleConfigured();
  return (
    <main className="nx-dark-island flex min-h-dvh items-center justify-center bg-[#05060a] px-4 text-white">
      <div className="w-full max-w-sm space-y-6 rounded-2xl border border-white/10 bg-white/[0.03] p-8">
        <CyrusWordmark height={28} />
        <h1 className="text-xl font-semibold">{mode === "create" ? "Create your Cyrus account" : "Sign in to Cyrus"}</h1>
        {sp.signed_out === "1" && <p className="text-sm text-white/60">You're signed out of Cyrus and Nxeon.</p>}
        {err && <p role="alert" className="rounded-lg bg-red-500/10 p-3 text-sm text-red-300">{err}</p>}
        <a href={q(mode === "create" ? "create" : undefined)} className="block rounded-lg bg-white px-4 py-2.5 text-center font-medium text-black">
          {mode === "create" ? "Create account with Nxeon" : "Sign in with Nxeon"}
        </a>
        {google && (
          // Google branding: neutral (white) button, the unmodified multicolour "G", Google's wording ("Continue with Google").
          <a href={`/api/auth/google?next=${encodeURIComponent(next)}`} data-testid="continue-with-google" className="flex items-center justify-center gap-3 rounded-lg border border-[#dadce0] bg-white px-4 py-2.5 font-medium text-[#1f1f1f]">
            <svg aria-hidden="true" width="18" height="18" viewBox="0 0 48 48"><path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/><path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"/><path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"/><path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/></svg>
            Continue with Google
