// Cyrus FIRST-OPEN step ("Welcome to Cyrus"): the pure rules. No DB, no Nxeon imports (unit-tested in
// test/cyrus-onboarding.test.ts).
//
// One interstitial, shown on BOTH hosts (nxeon.cloud/dashboard/cyrus and cyrus.my) the first time an account that may
// use Cyrus opens it: choose the public username (author tag) and accept the Cyrus Terms + Privacy Policy. The two are
// recorded together. What counts as "done" is decided here and only here:
//
//   username  : the account has a CyrusCreator.usernameKey (rules: ./username.ts)
//   terms     : the account accepted a CYRUS_LEGAL.version with the SAME MAJOR as the current one ("1.0" accepted covers
//               "1.3"; "2.0" asks again). A minor edit never interrupts anybody.
//
// The gate is the same switch as the username gate (./username-gate.ts, CYRUS_USERNAME_REQUIRED=0 turns BOTH off).

export type OnboardingNeed = "username" | "terms";

/** "1.3" -> "1". Unparseable / empty -> null. */
export function termsMajor(v: string | null | undefined): string | null {
  const m = /^\s*(\d{1,4})(?:\.\d{1,4})*\s*$/.exec(String(v ?? ""));
  return m ? m[1] : null;
}

/** Does an acceptance of `accepted` still cover the current terms version? */
export function termsCovered(accepted: string | null | undefined, current: string): boolean {
  const a = termsMajor(accepted);
  const c = termsMajor(current);
  return a !== null && c !== null && a === c;
}

/** What this account still has to do before Cyrus opens. Empty = nothing. */
export function onboardingNeeds(i: { usernameKey: string | null | undefined; termsVersion: string | null | undefined; currentTerms: string }): OnboardingNeed[] {
  const out: OnboardingNeed[] = [];
  if (!i.usernameKey) out.push("username");
  if (!termsCovered(i.termsVersion, i.currentTerms)) out.push("terms");
  return out;
}

export type WelcomeInput = { username?: unknown; acceptTerms?: unknown; termsVersion?: unknown };
export type WelcomeCheck =
  | { ok: true; wantsUsername: boolean }
  | { ok: false; code: "username_required" | "terms_required" | "terms_changed"; message: string };

/**
 * Validate a submission against what the account still needs. The terms version the browser SAW must equal the current
 * version (so a person never "accepts" text they were not shown); the stored value is always the server's current one.
 */
export function checkWelcomeInput(needs: readonly OnboardingNeed[], input: WelcomeInput, currentTerms: string): WelcomeCheck {
  const wantsUsername = needs.includes("username");
  if (wantsUsername && (typeof input.username !== "string" || !input.username.trim())) return { ok: false, code: "username_required", message: "Choose a username." };
  if (needs.includes("terms") || input.acceptTerms === true) {
    if (input.acceptTerms !== true) return { ok: false, code: "terms_required", message: "Tick the box to accept the Terms and the Privacy Policy." };
    if (typeof input.termsVersion !== "string" || input.termsVersion !== currentTerms) return { ok: false, code: "terms_changed", message: "The Terms were just updated. Reload this page and read them again." };
  }
  return { ok: true, wantsUsername };
}

/** The Terms / Privacy links for the host the person is on (cyrus.my serves its own /legal pages; nxeon.cloud has the Cyrus copies). */
export function legalLinks(onCyrusHost: boolean): { terms: string; privacy: string } {
  return onCyrusHost ? { terms: "/legal/terms", privacy: "/legal/privacy" } : { terms: "/legal/cyrus-terms", privacy: "/legal/cyrus-privacy" };
}

