"use client";
// "Welcome to Cyrus": the ONE first-open interstitial. The account must choose its public author tag (username) and accept
// the Cyrus Terms + Privacy Policy before it can use Cyrus (studio, app, builds, API). Shown in place of the Cyrus pages on
// BOTH hosts (nxeon.cloud portal and cyrus.my) from app/dashboard/cyrus/layout.tsx. Also used (mode="change") by the
// account page. Live availability uses /api/cyrus/username (rate limited). The browser sends the Terms version it SHOWED;
// the server refuses a stale one, so nobody accepts text they were not shown.
//
// States: first/username+terms (brand new), first/terms-only (has a name, the Terms moved to a new major version),
// done (saved: "Opening Cyrus", with a manual Continue link; the page refreshes itself, it never reloads in a loop).
import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";

type Check = { state: "idle" | "checking" | "ok" | "bad"; message?: string };
type Need = "username" | "terms";

export function UsernameGate({
  mode = "first", current = null, suggestion = null, nextChangeAt = null, onDone,
  needs = ["username"], termsVersion = null, termsHref = "/legal/terms", privacyHref = "/legal/privacy", reaccept = false,
}: {
  mode?: "first" | "change"; current?: string | null; suggestion?: string | null; nextChangeAt?: string | null; onDone?: () => void;
  /** first mode: what is still missing. "terms" adds the accept box. */
  needs?: Need[];
  /** CYRUS_LEGAL.version the page SHOWS (sent back so the server can refuse a stale acceptance). */
  termsVersion?: string | null;
  termsHref?: string;
  privacyHref?: string;
  /** the account accepted an older major version before: say the Terms changed. */
  reaccept?: boolean;
}) {
  const router = useRouter();
  const first = mode === "first";
  const needName = !first || needs.includes("username");
  const needTerms = first && needs.includes("terms");
  const [value, setValue] = useState(first ? (needName ? suggestion ?? "" : current ?? "") : current ?? "");
  const [check, setCheck] = useState<Check>({ state: "idle" });
  const [accepted, setAccepted] = useState(false);
  const [saving, setSaving] = useState(false);
  const [done, setDone] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const seq = useRef(0);
  const locked = mode === "change" && !!nextChangeAt;

  useEffect(() => {
    if (!needName) return;
    const v = value.trim();
    if (!v || (mode === "change" && v === current)) { setCheck({ state: "idle" }); return; }
    const mine = ++seq.current;
    setCheck({ state: "checking" });
    const t = setTimeout(async () => {
      try {
        const r = await fetch(`/api/cyrus/username?name=${encodeURIComponent(v)}`, { cache: "no-store" });
        const j = (await r.json()) as { ok?: boolean; message?: string; error?: string };
        if (mine !== seq.current) return;
        if (r.status === 429) setCheck({ state: "bad", message: j.error ?? "Too many checks. Wait a moment." });
        else setCheck(j.ok ? { state: "ok", message: "Available" } : { state: "bad", message: j.message ?? j.error ?? "Not available" });
      } catch {
        if (mine === seq.current) setCheck({ state: "bad", message: "Could not check right now." });
      }
    }, 350);
    return () => clearTimeout(t);
  }, [value, mode, current, needName]);

  const nameReady = !needName || check.state === "ok";
  const termsReady = !needTerms || accepted;
  const canSave = !saving && !done && !locked && nameReady && termsReady;

  async function save(e: React.FormEvent) {
    e.preventDefault();
    if (!canSave) return;
    setSaving(true); setErr(null);
    try {
      const body: Record<string, unknown> = {};
      if (needName) body.username = value.trim();
      if (needTerms) { body.acceptTerms = true; body.termsVersion = termsVersion; }
      const r = await fetch("/api/cyrus/username", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
      const j = (await r.json()) as { ok?: boolean; message?: string; error?: string; code?: string };
      if (j.ok) {
        setDone(true);
        onDone?.();
        router.refresh();
        return;
      }
      setErr(j.message ?? j.error ?? "Could not save.");
    } catch { setErr("Could not save. Try again."); }
    setSaving(false);
  }

  const heading = !first ? "Your Cyrus username"
    : needName ? "Welcome to Cyrus: choose your username"
    : reaccept ? "The Cyrus Terms have been updated" : "Welcome to Cyrus: one last step";
  return (
    <div className={first ? "mx-auto flex min-h-[70vh] w-full max-w-[520px] items-center px-4 py-10" : "w-full"}>
      <form onSubmit={save} className="w-full rounded-[16px] border border-white/12 bg-white/[0.04] p-6" data-testid="username-gate" aria-labelledby="cyrus-username-h">
        <h1 id="cyrus-username-h" className="text-[20px] font-semibold text-white">{heading}</h1>
        <p className="mt-2 text-[13px] leading-relaxed text-white/70">
          {!first
            ? "Your author tag on public mods. You can change it once every 30 days; your old name is held for you for 90 days."
            : needName
              ? "This is your author tag. It is shown on every mod you make public, instead of your account name. It must be unique."
              : reaccept
                ? "Please read the updated Terms and Privacy Policy and accept them to keep using Cyrus."
                : "Accept the Cyrus Terms and Privacy Policy to start building."}
        </p>
        {first && !needName && current ? <p className="mt-3 text-[13px] text-white/80">Your username: <b className="text-white">{current}</b></p> : null}
        {needName ? (
          <>
            <label htmlFor="cyrus-username" className="mt-5 block text-[12px] font-semibold uppercase tracking-wide text-white/60">Username</label>
            <input
              id="cyrus-username" name="username" autoComplete="off" autoCapitalize="none" spellCheck={false} maxLength={20}
              value={value} onChange={(e) => setValue(e.target.value)} disabled={locked || done}
              aria-describedby="cyrus-username-help" aria-invalid={check.state === "bad"}
              className="mt-1.5 w-full rounded-[11px] border border-white/20 bg-black/30 px-3.5 py-2.5 text-[15px] text-white outline-none focus:border-white/50"
              placeholder="your_name"
            />
            <p id="cyrus-username-help" className="mt-2 min-h-[20px] text-[12.5px]" role="status" aria-live="polite">
              {locked ? <span className="text-white/70">You can change it again on {nextChangeAt!.slice(0, 10)}.</span>
                : check.state === "checking" ? <span className="text-white/60">Checking...</span>
                : check.state === "ok" ? <span className="text-emerald-300">Available</span>
                : check.state === "bad" ? <span className="text-red-300">{check.message}</span>
                : <span className="text-white/55">3 to 20 characters: letters, numbers, underscore, hyphen.</span>}
            </p>
          </>
        ) : null}
        {needTerms ? (
          <label className="mt-4 flex items-start gap-2.5 text-[13px] leading-snug text-white/80">
            <input type="checkbox" name="accept" checked={accepted} onChange={(e) => setAccepted(e.target.checked)} disabled={done} className="mt-0.5 h-4 w-4 flex-none accent-white" data-testid="accept-terms" />
            <span>
              I have read and accept the Cyrus <a href={termsHref} target="_blank" rel="noopener noreferrer" className="underline">Terms of Service</a> and{" "}
              <a href={privacyHref} target="_blank" rel="noopener noreferrer" className="underline">Privacy Policy</a>
              {termsVersion ? <span className="text-white/50"> (version {termsVersion})</span> : null}.
            </span>
          </label>
        ) : null}
        {err ? <p className="mt-2 text-[12.5px] text-red-300" role="alert">{err}</p> : null}
        {done ? <p className="mt-3 text-[13px] text-emerald-300" role="status">Saved. Opening Cyrus...</p> : null}
        <button type="submit" disabled={!canSave} className="mt-4 inline-flex w-full items-center justify-center rounded-[11px] bg-white px-4 py-2.5 text-[14px] font-semibold text-black transition disabled:cursor-not-allowed disabled:opacity-40">
          {saving ? "Saving..." : done ? "Saved" : first ? "Continue to Cyrus" : "Save username"}
        </button>
        {done && first ? <p className="mt-2 text-center text-[12px] text-white/60">Not moving? <a href="" className="underline">Continue</a></p> : null}
        {first ? <p className="mt-3 text-[11.5px] text-white/50">{needName ? "You cannot use Cyrus until you pick one. Names that imitate Nxeon, Cyrus or staff are not allowed." : "You cannot use Cyrus until you accept."}</p> : null}
      </form>
    </div>
  );
}

