import { Inter, JetBrains_Mono, Space_Grotesk } from "next/font/google";
import "./cyrus.css";
import "./studio.css";
import { NotificationBell } from "@/components/cyrus/NotificationBell";
import { headers } from "next/headers";
import { UsernameGate } from "@/components/cyrus/username/UsernameGate";
import { modBuilderUserPendingUsername } from "@/lib/modbuilder/access";
import { usernameRequired } from "@/lib/cyrus-mods/username-gate";
import { onboardingStateFor, suggestUsername } from "@/lib/cyrus-mods/username-store";
import { legalLinks } from "@/lib/cyrus-mods/onboarding";
import { CYRUS_HOST_HEADER } from "@/lib/cyrus/bridge/config";

// Cyrus v5 typefaces (the handoff's), scoped to the studio: the variables only exist on the
// .cyrus-root wrapper, so the rest of the portal keeps its own fonts.
const inter = Inter({ subsets: ["latin"], variable: "--font-inter", display: "swap" });
const space = Space_Grotesk({ subsets: ["latin"], variable: "--font-space", display: "swap" });
const mono = JetBrains_Mono({ subsets: ["latin"], variable: "--font-jb", display: "swap" });

/**
 * Every Cyrus route renders inside this box: the portal's sidebar and top bar stay, the studio
 * fills the content area (components/nx/Shell.tsx gives /dashboard/cyrus an app frame).
 * `nx-dark-island` opts the studio out of the portal's generated light-mode retargeting: Cyrus
 * has its own deliberate light theme (studio.css), driven by the same portal toggle.
 * The pages themselves call the preview gate (shared.tsx / cores/page.tsx); this layout renders
 * no data.
 */
export default async function CyrusLayout({ children }: { children: React.ReactNode }) {
  // First-open gate ("Welcome to Cyrus": username + Terms, both hosts: this tree serves nxeon.cloud/dashboard/cyrus AND
  // cyrus.my). An account that may use Cyrus but has not finished the step sees only that screen. Pages and actions ALSO
  // refuse (modBuilderAccess), so this is not the lock. A read error never gates (the access rule decides).
  let gate: { needs: ("username" | "terms")[]; suggestion: string | null; username: string | null; terms: string; reaccept: boolean; links: { terms: string; privacy: string } } | undefined;
  if (usernameRequired()) {
    const u = await modBuilderUserPendingUsername().catch(() => null);
    const st = u ? await onboardingStateFor(u.id).catch(() => null) : null;
    if (st && st.needs.length) {
      const onCyrusHost = (await headers()).get(CYRUS_HOST_HEADER) === "1";
      gate = {
        needs: st.needs, username: st.username, terms: st.currentTerms, reaccept: !!st.termsVersion,
        suggestion: st.needs.includes("username") ? await suggestUsername().catch(() => null) : null,
        links: legalLinks(onCyrusHost),
      };
    }
  }
  // r40: the one Cyrus notification bell (fixed, top right of the studio). Not rendered unless CYRUS_NOTIFY=1.
  const bell = process.env.CYRUS_NOTIFY === "1";
  return (
    <div className={`cyrus-root nx-dark-island antialiased ${inter.variable} ${space.variable} ${mono.variable}`}>
      {bell ? <div className="fixed bottom-[7.5rem] left-3 z-40 max-sm:bottom-[5.25rem] max-sm:left-auto max-sm:right-[4.75rem]"><NotificationBell /></div> : null}
      {gate ? <UsernameGate mode="first" needs={gate.needs} suggestion={gate.suggestion} current={gate.username} termsVersion={gate.terms} termsHref={gate.links.terms} privacyHref={gate.links.privacy} reaccept={gate.reaccept} /> : children}
    </div>
  );
}

