          <Section title="Outcome by tier" sub="the customer's model choice; cost per kept success is the number to bring down">
            <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Tier</th><th>Builds</th><th>Succeeded</th><th>Kept</th><th>Re-requested</th><th>Spend</th><th>Avg turns</th><th>$ / success</th><th>$ / kept</th></tr></thead>
              <tbody>{s.byTier.map((g) => <tr key={g.key} className={tdRow}><td>{g.key}</td><td>{n(g.builds)}</td><td>{n(g.succeeded)}</td><td>{n(g.kept)}</td><td>{n(g.reworked)}</td><td>{usd(g.costUsd)}</td><td>{g.avgTurns}</td><td>{usd(g.costPerSuccess, 3)}</td><td>{usd(g.costPerKept, 3)}</td></tr>)}</tbody></table></TableWrap>
          </Section>

          <Section title="Token levers, ranked" sub="estimates with stated assumptions (no token counts are stored for old builds); score = mid saving / risk weight">
            {out.levers.length ? (
              <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Lever</th><th>Risk</th><th>Confidence</th><th>Saving (sample)</th><th>% of spend</th></tr></thead>
                <tbody>{out.levers.map((l) => <tr key={l.id} className={tdRow}><td className="min-w-[16rem]"><b>{l.title}</b><div className="text-xs text-slate-500">{l.change}</div></td><td><Badge tone={l.risk === "low" ? "green" : l.risk === "medium" ? "amber" : "red"}>{l.risk}</Badge></td><td>{l.confidence}</td><td className="whitespace-nowrap">{usd(l.savingUsd.low)} – {usd(l.savingUsd.high)}</td><td>{pct(l.savingPct)}</td></tr>)}</tbody></table></TableWrap>
            ) : <Empty>No levers in the job output.</Empty>}
          </Section>

          <Section title="Path memory" sub={`prompt shape (archetype / lanes / fresh or change / complexity) -> the path that kept the most at the lowest cost. Suggestions only; a shape needs ${8} builds before it is used.`}>
            {out.paths.length ? (
              <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Shape</th><th>Builds</th><th>Usual path</th><th>Best path</th><th>Kept</th><th>$ / kept</th><th>Typical / up to</th></tr></thead>
                <tbody>{out.paths.slice(0, 40).map((r) => <tr key={JSON.stringify(r.shape)} className={tdRow}><td className="font-mono text-xs">{r.shape.archetype} · {r.shape.laneKey} · {r.shape.kind} · {r.shape.complexity}</td><td>{n(r.n)}{r.usable ? "" : <span className="text-xs text-slate-500"> (too few)</span>}</td><td className="text-xs">{r.current ? `${r.current.tier} · ${r.current.effort} · ${r.current.path}` : "-"}</td><td className="text-xs">{r.best ? `${r.best.tier} · ${r.best.effort} · ${r.best.path}` : "-"}</td><td>{r.bestStats ? pct(r.bestStats.keptRate) : r.currentStats ? pct(r.currentStats.keptRate) : "-"}</td><td>{usd((r.bestStats ?? r.currentStats)?.costPerKept ?? null, 3)}</td><td className="whitespace-nowrap">{r.estimate ? `${usd(r.estimate.typicalUsd, 2)} / ${usd(r.estimate.upToUsd, 2)}` : "-"}</td></tr>)}</tbody></table></TableWrap>
            ) : <Empty>No path memory yet: run the mining job (it writes pathmemory.json).</Empty>}
            {out.recipeEffects.length ? (
              <TableWrap><table className="mt-3 w-full text-sm"><thead><tr className={thCls}><th>Recipe (A/B)</th><th>Builds</th><th>With: kept / $ per kept</th><th>Holdback: kept / $ per kept</th><th>Ratio</th></tr></thead>
                <tbody>{out.recipeEffects.map((e) => <tr key={e.recipeId} className={tdRow}><td className="font-mono text-xs">{e.recipeId}</td><td>{n(e.n)}</td><td>{e.with ? `${pct(e.with.keptRate)} / ${usd(e.with.costPerKept, 3)}` : "-"}</td><td>{e.without ? `${pct(e.without.keptRate)} / ${usd(e.without.costPerKept, 3)}` : "-"}</td><td>{e.ratio ?? "-"}</td></tr>)}</tbody></table></TableWrap>
            ) : null}
          </Section>

          <Section title={`Review queue (${open} open of ${queue.length})`} sub="proposed rules, sheet facts, golden cases, routing hints, recipe / starter-bank gaps and coach gaps. Accept = a person writes it in a normal branch with tests and ships it as an eval-gated engine release; nothing here is ever applied automatically.">
            {queue.length ? (
              <ul className="space-y-2">{queue.map((c) => (
                <li key={c.id} className="rounded-lg border border-white/[0.08] px-3 py-2 text-sm" data-candidate={c.id}>
                  <div className="flex flex-wrap items-center gap-2"><Badge tone={KIND_TONE[c.kind]}>{c.kind}</Badge><Badge tone={STATUS_TONE[c.review.status]}>{c.review.status}</Badge><b className="min-w-0 flex-1">{c.title}</b><span className="text-xs text-slate-500">confidence {c.confidence}</span></div>
                  <p className="mt-1 text-xs text-slate-400">{c.rationale}</p>
                  {c.review.last ? <p className="mt-1 text-xs text-slate-500">{c.review.last.decision} {c.review.last.at.replace("T", " ").slice(0, 16)} UTC{c.review.last.note ? `: ${c.review.last.note}` : ""}</p> : null}
                  <details className="mt-1"><summary className="cursor-pointer text-xs text-slate-500">proposed text and evidence</summary>
                    <p className="mt-1 whitespace-pre-wrap break-words text-xs">{c.proposedText}</p>
                    <p className="mt-1 text-xs">{c.evidence.map((id) => <Link key={id} className="mr-2 font-mono underline" href={`/admin/cyrus/builds/${id}`}>{id.slice(0, 12)}</Link>)}</p>
                  </details>
                  <form action={adminCyrusLearningReview} className="mt-2 flex flex-wrap items-center gap-2">
                    <input type="hidden" name="candidateId" value={c.id} />
                    <input type="hidden" name="back" value="/admin/cyrus/learning" />
                    <input name="note" maxLength={300} placeholder="note (required to reject)" className="input min-w-[12rem] flex-1 text-xs" aria-label={`Note for ${c.id}`} />
                    {c.review.status !== "accepted" ? <button type="submit" name="decision" value="accepted" className="btn-secondary text-xs">Accept</button> : null}
                    {c.review.status !== "rejected" ? <button type="submit" name="decision" value="rejected" className="btn-secondary text-xs">Reject</button> : null}
                    {c.review.status !== "candidate" ? <button type="submit" name="decision" value="reopened" className="btn-secondary text-xs">Reopen</button> : null}
                  </form>
                </li>
              ))}</ul>
            ) : <Empty>No candidates: nothing failed, regressed or was re-requested in the analysed builds.</Empty>}
          </Section>
        </>
      )}
    </div>
  );
}

