export async function openPlanCheckout(user: User, tier: PlanTier, opts: { returnBase?: string } = {}): Promise<CheckoutOpen> {
  if (!configured()) return { ok: false, error: "Payments aren't available right now." };
  const cfg = await loadTokenConfig();
  const price = (await planPrices(cfg))[tier];
  if (!price) return { ok: false, error: "Plans aren't set up yet. Please try again later." };
  const cur = await db.cyrusPlan.findUnique({ where: { userId: user.id } });
  if (cur && ACTIVE.includes(cur.status) && !cur.endedAt) return { ok: false, error: "You already have a plan. Change it from your plan instead." };
  const customer = await customerFor(user);
  const session = await (override ? sc().checkout.sessions.create.bind(sc().checkout.sessions) : createCheckoutSessionLogged)({
    mode: "subscription",
    customer,
    ui_mode: uiMode(),
    payment_method_types: ["card"],
    line_items: [{ price: price.id, quantity: 1 }],
    return_url: `${opts.returnBase ?? appBase()}/api/cyrus/tokens/return?session_id={CHECKOUT_SESSION_ID}`,
    metadata: { cyrusUserId: user.id, cyrusKind: "plan", cyrusTier: tier },
    subscription_data: { metadata: { cyrusUserId: user.id, cyrusTier: tier }, description: `Cyrus ${tier === "all" ? "All models" : tier[0].toUpperCase() + tier.slice(1)} plan` },
  }, requestOpts());
  return session.client_secret ? { ok: true, clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : { ok: false, error: "Couldn't open checkout." };
}

export async function openTopupCheckout(user: User, cents: number, opts: { returnBase?: string } = {}): Promise<CheckoutOpen> {
  if (!configured()) return { ok: false, error: "Payments aren't available right now." };
  const cfg = await loadTokenConfig();
  if (!cfg.topup.enabled) return { ok: false, error: "Top-ups aren't available right now." };
  if (!validTopupCents(cents, cfg)) return { ok: false, error: `Pick an amount from $${(cfg.topup.minCents / 100).toFixed(0)} to $${(cfg.topup.maxCents / 100).toFixed(0)}.` };
  if (cfg.topup.requiresPaid) {
    const paid = await getHost().servers.paidCount(user.id) + await db.cyrusPlan.count({ where: { userId: user.id } });
    if (!paid) return { ok: false, error: "Top-ups are for customers with a game server or a Cyrus plan." };
  }
  const tokens = topupTokens(cents, cfg);
  const customer = await customerFor(user);
  const md = { cyrusUserId: user.id, cyrusKind: "topup", cyrusTokens: String(tokens), cyrusCents: String(cents) };
  const session = await (override ? sc().checkout.sessions.create.bind(sc().checkout.sessions) : createCheckoutSessionLogged)({
    mode: "payment",
    customer,
    ui_mode: uiMode(),
    payment_method_types: ["card"],
    line_items: [{ price_data: { currency: "usd", unit_amount: cents, product_data: { name: `${fmt(tokens)} Cyrus tokens` } }, quantity: 1 }],
    return_url: `${opts.returnBase ?? appBase()}/api/cyrus/tokens/return?session_id={CHECKOUT_SESSION_ID}`,
    metadata: md,
    payment_intent_data: { metadata: md, description: `${fmt(tokens)} Cyrus tokens` },
  }, requestOpts());
  return session.client_secret ? { ok: true, clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : { ok: false, error: "Couldn't open checkout." };
}

/** A paid top-up session -> tokens (idempotent per session). Returns tokens granted (0 if replay/unpaid). */
export async function fulfilTopup(session: Stripe.Checkout.Session): Promise<number> {
  const md = session.metadata ?? {};
  if (md.cyrusKind !== "topup" || !md.cyrusUserId || session.payment_status !== "paid" || session.mode !== "payment") return 0;
  const cfg = await loadTokenConfig();
  const paidCents = session.amount_total ?? 0;
  // The amount actually paid decides the tokens; the metadata figure is only a cap.
  const tokens = Math.min(Number(md.cyrusTokens) || 0, topupTokens(paidCents, cfg));
  // r44: through the purchase path (direct credit, or the signed webhook/outbox when CYRUS_PURCHASE_EVENTS=1), same
  // idemKey as before, so a return-leg + webhook race or a redelivery still credits exactly once
  const r = await deliverPurchase(topupSessionEnvelope(session, md.cyrusUserId, tokens, paidCents, cfg));
  return r.tokens;
}

// Card: a monthly subscription on Nxeon's Stripe (built; NOT run against Stripe)
// ---------------------------------------------------------------------------

export async function openStorageCheckout(user: { id: string; email: string; name?: string | null; stripeCustomerId: string | null; stripePaymentMethodId: string | null }, gb: number, opts: { returnBase?: string } = {}): Promise<{ ok: true; clientSecret: string; publishableKey: string } | { ok: false; error: string }> {
  const s = getHost().billing.stripe;
  if (!storageAddonsEnabled() || !s?.configured()) return { ok: false, error: "Paying by card isn't available right now." };
  const cfg = await loadStorageConfig();
  if (!Number.isInteger(gb) || gb < 1 || gb > cfg.addonMaxGb) return { ok: false, error: `Pick 1 to ${cfg.addonMaxGb} GB.` };
  const cur = await db.cyrusStorageAccount.findUnique({ where: { userId: user.id } });
  if (cur && effectiveAddonGb(cur, new Date()) > 0) return { ok: false, error: "You already have extra storage. Change it from your storage settings." };
  const customer = await s.ensureCustomer(user);
  const md = { cyrusUserId: user.id, cyrusKind: "storage", cyrusGb: String(gb) };
  const session = await s.createCheckoutSession({
    mode: "subscription", customer, ui_mode: s.uiMode, payment_method_types: ["card"],
    line_items: [{ price_data: { currency: "usd", unit_amount: storagePriceCents(gb, cfg.rule, cfg.table), recurring: { interval: "month" }, product_data: { name: `Cyrus storage +${gb} GB` } }, quantity: 1 }],
    return_url: `${opts.returnBase ?? process.env.APP_URL ?? "http://localhost:3000"}/api/cyrus/storage/return?session_id={CHECKOUT_SESSION_ID}`,
    metadata: md, subscription_data: { metadata: md, description: `Cyrus storage +${gb} GB` },
  }, s.requestOptions);
  return session.client_secret ? { ok: true, clientSecret: session.client_secret, publishableKey: s.publishableKey() } : { ok: false, error: "Couldn't open checkout." };
}

const subMeta = (sub: Stripe.Subscription | null | undefined) => (sub?.metadata?.cyrusKind === "storage" && sub.metadata.cyrusUserId ? { userId: sub.metadata.cyrusUserId, gb: Number(sub.metadata.cyrusGb) } : null);

// Create (or find) the three Cyrus plan products + monthly prices in Stripe.
//
//   STRIPE_SECRET_KEY=sk_test_... npx tsx scripts/cyrus-tokens-stripe-setup.ts
//
// TEST MODE ONLY by default: refuses an sk_live_/rk_live_ key unless BOTH
// CYRUS_STRIPE_ALLOW_LIVE=1 and --live are given (an owner decision; never run by an agent).
// Idempotent: prices are found by lookup_key (cyrus_plan_<tier>_v1, which the portal reads)
// and only created when missing. Changing a price later = a NEW price with lookup_key ..._v2
// plus transfer_lookup_key, never an edit (Stripe prices are immutable).
import Stripe from "stripe";
import { CYRUS_TOKEN_DEFAULTS } from "../lib/cyrus/tokens/config";
import { PLAN_LOOKUP_KEY } from "../lib/cyrus/tokens/economy";

const key = process.env.STRIPE_SECRET_KEY || "";
const live = /^(sk|rk)_live_/.test(key);
if (!key) { console.error("STRIPE_SECRET_KEY is not set"); process.exit(1); }
if (live && !(process.env.CYRUS_STRIPE_ALLOW_LIVE === "1" && process.argv.includes("--live"))) {
  console.error("Refusing: this is a LIVE key. Cyrus products are created in TEST mode only (owner: CYRUS_STRIPE_ALLOW_LIVE=1 ... --live).");
  process.exit(2);
}
const stripe = new Stripe(key);
const TIERS = [
  { tier: "katara", name: "Cyrus Katara plan", cents: Number(CYRUS_TOKEN_DEFAULTS.cyrus_tok_plan_katara_cents), tokens: CYRUS_TOKEN_DEFAULTS.cyrus_tok_plan_katara_tokens, models: "Katara" },
  { tier: "saka", name: "Cyrus Saka plan", cents: Number(CYRUS_TOKEN_DEFAULTS.cyrus_tok_plan_saka_cents), tokens: CYRUS_TOKEN_DEFAULTS.cyrus_tok_plan_saka_tokens, models: "Katara, Saka" },
  { tier: "all", name: "Cyrus All models plan", cents: Number(CYRUS_TOKEN_DEFAULTS.cyrus_tok_plan_all_cents), tokens: CYRUS_TOKEN_DEFAULTS.cyrus_tok_plan_all_tokens, models: "Katara, Saka, Yakko" },
] as const;

async function main() {
  const existing = await stripe.prices.list({ lookup_keys: TIERS.map((t) => PLAN_LOOKUP_KEY(t.tier)), active: true, limit: 10, expand: ["data.product"] });
  for (const t of TIERS) {
    const lk = PLAN_LOOKUP_KEY(t.tier);
    const have = existing.data.find((p) => p.lookup_key === lk);
    if (have) { console.log(`${t.tier}: exists ${have.id} (${have.unit_amount} ${have.currency}/${have.recurring?.interval}) livemode=${have.livemode}`); continue; }
    const product = await stripe.products.create({
      name: t.name,
      description: `${Number(t.tokens).toLocaleString("en-US")} Cyrus tokens every month · models: ${t.models} · Beta, Minecraft Java`,
      metadata: { cyrus_tier: t.tier },
    }, { idempotencyKey: `cyrus-product-${t.tier}-v1-${live ? "live" : "test"}` });
    const price = await stripe.prices.create({
      product: product.id, currency: "usd", unit_amount: t.cents, recurring: { interval: "month" },
      lookup_key: lk, metadata: { cyrus_tier: t.tier, cyrus_tokens: String(t.tokens) },
      nickname: `${t.name} monthly`,
    }, { idempotencyKey: `cyrus-price-${t.tier}-v1-${live ? "live" : "test"}` });
    console.log(`${t.tier}: created ${price.id} on ${product.id} (${t.cents} usd/month) livemode=${price.livemode}`);
  }
}
main().catch((e) => { console.error(e); process.exit(1); });

