const EMAIL_RE = /^[^\s@<>"',;]{1,64}@[^\s@<>"',;]{1,253}\.[A-Za-z]{2,24}$/;
export const normEmail = (e: string) => e.trim().toLowerCase();

export function parseList(raw: string | null | undefined): string[] {
  return [...new Set((raw ?? "").split(/[,\s;]+/).map(normEmail).filter((e) => EMAIL_RE.test(e)))];
}
export const formatList = (l: string[]) => l.join(",");

export type AddResult = { next: string[]; added: string[]; already: string[]; invalid: string[]; full: string[] };

/** Add pasted addresses (any separator). Never removes anything; reports what was skipped and why. */
export function addEmails(current: string[], input: string): AddResult {
  const next = [...current];
  const added: string[] = [], already: string[] = [], invalid: string[] = [], full: string[] = [];
  for (const tok of input.split(/[,\s;]+/).map((t) => t.trim()).filter(Boolean)) {
    const e = normEmail(tok);
    if (!EMAIL_RE.test(e)) { invalid.push(tok.slice(0, 80)); continue; }
    if (next.includes(e)) { if (!already.includes(e)) already.push(e); continue; }
    if (next.length >= MAX_LIST) { full.push(e); continue; }
    next.push(e); added.push(e);
  }
  return { next, added, already, invalid, full };
}

export function removeEmail(current: string[], email: string): { next: string[]; removed: boolean } {
  const e = normEmail(email);
  const next = current.filter((x) => x !== e);
  return { next, removed: next.length !== current.length };
}

/** The setting that records who was invited when (small JSON; email -> { at, wave }). */
export type InviteLog = Record<string, { at: string; wave: string }>;
export function parseInviteLog(raw: string | null | undefined): InviteLog {
  try {
    const j = JSON.parse(raw || "{}") as unknown;
    if (!j || typeof j !== "object") return {};
    const out: InviteLog = {};
    for (const [k, v] of Object.entries(j as Record<string, unknown>)) {
      const o = v as { at?: unknown; wave?: unknown };
      if (EMAIL_RE.test(k) && typeof o?.at === "string" && typeof o?.wave === "string") out[k] = { at: o.at.slice(0, 30), wave: o.wave.slice(0, 8) };
    }
    return out;
  } catch { return {}; }
}

const esc = (s: string) => s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);

/**
 * The invite email. TRANSACTIONAL class on purpose: a one-time, personal invitation for a hand-picked person, sent with no
 * List-Unsubscribe header and no marketing class (the host's mail stack only adds one-click unsubscribe to marketing sends).
 * It says why the person got it and how to stop further mail (reply). Sent at most once per address per wave by the admin tool.
 * No claims about quality or speed beyond what Cyrus does; the private beta is described as a beta.
 */
export function renderInvite(a: { email: string; cyrusOrigin: string; wave: WaveId; note?: string | null }): { subject: string; html: string; text: string } {
  const origin = a.cyrusOrigin.replace(/\/+$/, "");
  const href = `${origin}/sign-in?next=${encodeURIComponent("/studio")}`;
  const subject = "You're invited to the Cyrus private beta";
  const title = "You're in: Cyrus private beta";
  const note = (a.note ?? "").replace(/[\r\n]+/g, " ").trim().slice(0, 240);
  const body = [
    "Cyrus turns a plain-English description into a working Minecraft plugin you can install on your server.",
    `Sign in with the account that uses ${a.email} (your Nxeon account, or Google with this address). You will pick a username and accept the Terms once, then you can build.`,
    "It is a beta: builds can fail and we want to hear about it. Use \"Report a problem\" inside Cyrus, or reply to this email.",
    note,
  ].filter(Boolean).join(" ");
  const footer = `You received this one-time invitation because we added ${esc(a.email)} to the Cyrus private beta. It is not a newsletter and there is no list: reply &quot;stop&quot; and we will remove you.<br>Cyrus, a Nxeon product.`;
  const html = cyrusMailHtml({ subject, eyebrow: "Private beta", title, body, cta: "Open Cyrus", href, base: origin, footer });
  const text = `${title}\n\n${body}\n\nOpen Cyrus: ${href}\n\nYou received this one-time invitation because we added ${a.email} to the Cyrus private beta. Reply "stop" and we will remove you.\nCyrus, a Nxeon product.`;
  return { subject, html, text };
}
