// Admin "Beta invites" tab data: the private-beta allow-list with each invitee's funnel (signed in? username + Terms? first
// build? tokens?). READ ONLY aside from the actions in lib/actions-cyrus-admin.ts. Never selects prompts or message text.
import { cyrusDb as db } from "../db";
import { getHost } from "../host";
import { ALLOW_SETTING, BETA_TARGET, INVITES_SETTING, parseInviteLog, parseList } from "../beta/invites";

export type BetaRow = {
  email: string;
  /** a Nxeon/Cyrus account exists for this email */
  account: boolean;
  userId: string | null;
  verified: boolean;
  /** "Welcome to Cyrus" step */
  username: string | null;
  termsAccepted: boolean;
  builds: number;
  succeeded: number;
  refused: number;
  lastBuildAt: string | null;
  tokens: number | null;
  invitedAt: string | null;
  wave: string | null;
  /** the furthest funnel stage reached: invited -> account -> welcome -> built -> succeeded */
  stage: "invited" | "account" | "welcome" | "built" | "succeeded";
};

export type BetaView = { target: number; count: number; rows: BetaRow[]; stages: Record<BetaRow["stage"], number> };

export async function loadBeta(): Promise<BetaView> {
  const host = getHost();
  const [raw, logRaw] = await Promise.all([host.settings.get(ALLOW_SETTING, "").catch(() => ""), host.settings.get(INVITES_SETTING, "").catch(() => "")]);
  const emails = parseList(raw);
  const log = parseInviteLog(logRaw);
  const users = await Promise.all(emails.map((e) => host.users.find(e).catch(() => null)));
  const ids = users.filter((u): u is { id: string; email: string } => !!u).map((u) => u.id);
  const [creators, builds, accounts, verified] = await Promise.all([
    ids.length ? db.cyrusCreator.findMany({ where: { userId: { in: ids } }, select: { userId: true, username: true, termsVersion: true } }).catch(() => []) : [],
    ids.length ? db.modBuild.groupBy({ by: ["userId", "status", "errorCode"], where: { userId: { in: ids } }, _count: { _all: true }, _max: { createdAt: true } }).catch(() => []) : [],
    ids.length ? db.cyrusTokenAccount.findMany({ where: { userId: { in: ids } }, select: { userId: true, balance: true } }).catch(() => []) : [],
    ids.length ? host.users.emails(ids).catch(() => []) : [],
  ]);
  void verified;
  const cBy = new Map(creators.map((c) => [c.userId, c]));
  const aBy = new Map(accounts.map((a) => [a.userId, a.balance]));
  const rows: BetaRow[] = emails.map((email, i) => {
    const u = users[i];
    const c = u ? cBy.get(u.id) : undefined;
    const mine = u ? builds.filter((b) => b.userId === u.id) : [];
    const n = mine.reduce((s, b) => s + b._count._all, 0);
    const ok = mine.filter((b) => b.status === "succeeded").reduce((s, b) => s + b._count._all, 0);
    const refused = mine.filter((b) => b.errorCode === "refused").reduce((s, b) => s + b._count._all, 0);
    const last = mine.map((b) => b._max.createdAt).filter((d): d is Date => !!d).sort((a, b) => b.getTime() - a.getTime())[0] ?? null;
    const welcome = !!c?.username && !!c?.termsVersion;
    const stage: BetaRow["stage"] = ok > 0 ? "succeeded" : n > 0 ? "built" : welcome ? "welcome" : u ? "account" : "invited";
    return {
      email, account: !!u, userId: u?.id ?? null, verified: !!u, username: c?.username ?? null, termsAccepted: !!c?.termsVersion,
      builds: n, succeeded: ok, refused, lastBuildAt: last?.toISOString() ?? null, tokens: u ? (aBy.get(u.id) ?? null) : null,
      invitedAt: log[email]?.at ?? null, wave: log[email]?.wave ?? null, stage,
    };
  });
  const stages = { invited: 0, account: 0, welcome: 0, built: 0, succeeded: 0 } as Record<BetaRow["stage"], number>;
  for (const r of rows) stages[r.stage]++;
  return { target: BETA_TARGET, count: rows.length, rows, stages };
}
EOF
