/** Add emails to the private-beta allow-list and (optionally) send each the one-time invite. Audited; never removes anyone. */
export async function adminCyrusBetaAdd(fd: FormData) {
  const admin = await guard("beta.list");
  const { addEmails, parseList, formatList, ALLOW_SETTING, INVITES_SETTING, parseInviteLog, isWave, renderInvite } = await import("./cyrus/beta/invites");
  const before = await settingValue(ALLOW_SETTING);
  const cur = parseList(before);
  const r = addEmails(cur, String(fd.get("emails") ?? "").slice(0, 8000));
  const wave = isWave(str(fd, "wave", 4)) ? str(fd, "wave", 4) : "W0";
  if (!r.added.length && !r.already.length) go(fd, "err", r.invalid.length ? `Not valid email addresses: ${r.invalid.slice(0, 3).join(", ")}` : "Paste at least one email address.");
  if (r.added.length) await setOrClear(ALLOW_SETTING, formatList(r.next));
  let sent = 0, skipped = 0;
  const wantsMail = fd.get("send") === "1";
  if (wantsMail) {
    const log = parseInviteLog(await settingValue(INVITES_SETTING));
    const host = getHost();
    const from = (await host.settings.get("cyrus_mail_from", "").catch(() => "")).trim();
    const { validCyrusSender } = await import("./cyrus/notify/events");
    if (!host.mail || !validCyrusSender(from)) go(fd, "err", `Added ${r.added.length}, but the invite email is not set up: save a sender on @cyrus.my in Notifications (setting cyrus_mail_from) first.`);
    const { bridgeConfig } = await import("./cyrus/bridge/config");
    const cfg = bridgeConfig();
    for (const e of [...r.added, ...r.already]) {
      if (log[e]) { skipped++; continue; } // one invitation per address
      const m = renderInvite({ email: e, cyrusOrigin: cfg.enabled ? cfg.cyrusOrigin : "https://cyrus.my", assetBase: (process.env.APP_URL || "https://nxeon.cloud"), wave: wave as never, note: str(fd, "note", 240) });
      const ok = await host.mail.send({ to: e, from, subject: m.subject, html: m.html, text: m.text, userId: "" }).catch(() => false);
      if (ok) { log[e] = { at: new Date().toISOString(), wave }; sent++; }
    }
    if (sent) await setOrClear(INVITES_SETTING, JSON.stringify(log));
  }
  await cyrusAudit({ actorId: admin.id, action: "beta.invite", target: `beta:${wave}`, before: `${cur.length} on the list`, after: `${r.next.length} on the list (+${r.added.length}); ${sent} invite email(s) sent`, note: str(fd, "note") });
  go(fd, "ok", `Added ${r.added.length}${r.already.length ? `, ${r.already.length} already on the list` : ""}${r.invalid.length ? `, ${r.invalid.length} not valid` : ""}${wantsMail ? `; ${sent} invite(s) sent${skipped ? `, ${skipped} already invited` : ""}` : ""}.`);
}

/** Remove one email from the allow-list (never your own: the list is also the admin gate). */
export async function adminCyrusBetaRemove(fd: FormData) {
  const admin = await guard("beta.list");
  const { removeEmail, parseList, formatList, ALLOW_SETTING } = await import("./cyrus/beta/invites");
  const email = str(fd, "email", 254).toLowerCase();
  if (email === (admin.email ?? "").toLowerCase()) go(fd, "err", "Keep your own email on the list, or you lock yourself out of this page.");
  const before = await settingValue(ALLOW_SETTING);
  const r = removeEmail(parseList(before), email);
  if (!r.removed) go(fd, "err", "That address is not on the list.");
  await setOrClear(ALLOW_SETTING, formatList(r.next));
  await cyrusAudit({ actorId: admin.id, action: "beta.invite", target: `beta:remove`, before: email, after: `${r.next.length} on the list`, note: str(fd, "note") });
  go(fd, "ok", `${email} removed. Their account, builds and tokens are untouched; they can no longer open Cyrus.`);
}

// ── intake-guard refusal review (false positives) ───────────────────────────
''')
