import { createTicketCore } from "@/lib/reply-core";
import { composeTicketBody, ticketCategory } from "@/lib/support-intake";
import { mirrorNewTicketToDiscord } from "@/lib/discord-bridge";
import { modBuilderUserPendingUsername } from "@/lib/modbuilder/access";
import { checkRateLimit } from "@/lib/rate-limit";
import { cyrusDb } from "@/lib/cyrus/db";
import { attachTicketContext, contextSnapshot } from "@/lib/cyrus/support/context";
import { composeReport, parseReport, REPORT_TICKET_CATEGORY, type BuildFacts } from "@/lib/cyrus/support/report";
import { CYRUS_HOST_HEADER } from "@/lib/cyrus/bridge/config";
import { recordRequestActivity } from "@/lib/activity-request";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store" } });

export async function POST(req: Request) {
  // pending-welcome accounts may report too (a broken Welcome step is exactly when they need it)
  const user = await modBuilderUserPendingUsername().catch(() => null);
  if (!user) return json(404, { error: "Not found" });
  const origin = req.headers.get("origin");
  if (origin && origin !== new URL(req.url).origin) return json(403, { error: "cross-site" });
  const rl = checkRateLimit(`cyrus-report:${user.id}`, { max: 6, windowMs: 3_600_000 });
  const rl1 = checkRateLimit(`cyrus-report-min:${user.id}`, { max: 1, windowMs: 60_000 });
  if (!rl.ok || !rl1.ok) return json(429, { error: "You just sent one. Give it a minute, or add to the ticket you opened." });
  let raw: unknown;
  try { raw = await req.json(); } catch { return json(400, { error: "bad json" }); }
  const p = parseReport(raw);
  if (!p.ok) return json(400, { error: p.error });
  const { input } = p;

  let facts: BuildFacts | null = null;
  let snapId: string | null = null;
  if (input.buildId) {
    try {
      const b = await cyrusDb.modBuild.findUnique({ where: { id: input.buildId }, select: { id: true, userId: true, status: true, errorCode: true, error: true, mcVersion: true, pluginName: true, createdAt: true, prompt: true, changeRequest: true, result: true } });
      if (b && b.userId === user.id) {
        const snap = await contextSnapshot(user.id, b.id).catch(() => null);
        const res = (b.result ?? {}) as { events?: { at?: string; message?: string; text?: string; stage?: string; status?: string }[]; errorDetail?: string };
        facts = {
          buildId: b.id, status: b.status, errorCode: b.errorCode, error: b.error, errorDetail: res.errorDetail ?? null, mcVersion: b.mcVersion, name: b.pluginName,
          model: snap?.model ?? null, at: b.createdAt.toISOString(), flightVerdict: snap?.flight?.verdict ?? null, flightFailed: snap?.flight?.failed ?? [],
          events: (res.events ?? []).slice(-20).map((e) => ({ at: e.at, text: String(e.message ?? e.text ?? e.stage ?? e.status ?? "") })),
          prompt: b.prompt, changeRequest: b.changeRequest,
        };
        snapId = b.id;
      }
    } catch { /* the ticket still opens, without build facts */ }
  }
  const cyrusHost = req.headers.get(CYRUS_HOST_HEADER) === "1";
  const msg = composeReport(input, facts, { cyrusHost });
  try {
    const cat = ticketCategory(REPORT_TICKET_CATEGORY[input.category]);
    const t = await createTicketCore({ userId: user.id, subject: msg.subject, body: composeTicketBody({ category: cat, body: msg.body }), priority: input.category === "billing" ? "HIGH" : "NORMAL" });
    if (snapId) await attachTicketContext(t.ticketId, user.id, snapId).catch(() => false);
    await mirrorNewTicketToDiscord(t.ticketId);
    await recordRequestActivity({ type: "action.ticket", userId: user.id, label: "Reported a Cyrus problem", data: { op: "open", ticketId: t.ticketId, via: "cyrus-report" } }).catch(() => undefined);
    const nx = (process.env.APP_URL || "https://nxeon.cloud").replace(/\/+$/, "");
    return json(200, { ok: true, ticketId: t.ticketId, url: `${nx}/dashboard/support/${t.ticketId}` });
  } catch (e) {
    console.error("[cyrus-report]", (e as Error).message);
    return json(503, { error: "Could not send that right now. Email support@nxeon.cloud instead." });
  }
}
