// "Report a problem" from inside Cyrus (beta): the PURE half. Turns the person's note + a build's facts into one Nxeon support
// ticket body labelled [Cyrus beta], with the diagnostics support needs (build id, status, error, Test Flight verdict, the last
// build events) so nobody has to ask "which build?". The route (app/api/cyrus/report) does the IO. No DB, no Nxeon imports.
// Privacy: the person's PROMPT is included only when they tick the box; log lines are trimmed and scrubbed of secrets/tokens.

export const REPORT_CATEGORIES = ["bug", "wrong", "slow", "billing", "idea", "other"] as const;
export type ReportCategory = (typeof REPORT_CATEGORIES)[number];
export const REPORT_LABEL: Record<ReportCategory, string> = {
  bug: "Something broke or errored", wrong: "The result was wrong", slow: "It was slow or stuck", billing: "Tokens or billing", idea: "An idea or request", other: "Something else",
};
/** Nxeon ticket category (lib/support-intake.ts keys) each Cyrus category files under. */
export const REPORT_TICKET_CATEGORY: Record<ReportCategory, "game" | "billing" | "other"> = { bug: "game", wrong: "game", slow: "game", billing: "billing", idea: "other", other: "other" };

export type ReportInput = { what: string; category: ReportCategory; buildId: string | null; includeLogs: boolean; includePrompt: boolean; page: string | null };

const ID_RE = /^[A-Za-z0-9_-]{1,64}$/;
const CAT = new Set<string>(REPORT_CATEGORIES);

export function parseReport(raw: unknown): { ok: true; input: ReportInput } | { ok: false; error: string } {
  const b = (raw && typeof raw === "object" ? raw : {}) as Record<string, unknown>;
  const what = typeof b.what === "string" ? b.what.replace(/\r\n/g, "\n").trim() : "";
  if (what.length < 5) return { ok: false, error: "Tell us a little more (at least a sentence)." };
  if (what.length > 4000) return { ok: false, error: "That is too long. Keep it under 4000 characters." };
  const category = (typeof b.category === "string" && CAT.has(b.category) ? b.category : "bug") as ReportCategory;
  const buildId = typeof b.buildId === "string" && ID_RE.test(b.buildId) ? b.buildId : null;
  const page = typeof b.page === "string" && /^\/[A-Za-z0-9/_?=&.%-]{0,200}$/.test(b.page) ? b.page : null;
  return { ok: true, input: { what, category, buildId, includeLogs: b.includeLogs !== false, includePrompt: b.includePrompt === true, page } };
}

const SECRET = [
  /\bsk-[A-Za-z0-9_-]{10,}/g, /\b(?:cyk|rk|pk)_[A-Za-z0-9_]{8,}/g, /\bBearer\s+[A-Za-z0-9._~+/-]{12,}/gi, /\bgh[pousr]_[A-Za-z0-9]{20,}/g,
  /\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{5,}/g, /(?:password|secret|token|api[_-]?key)\s*[:=]\s*\S{4,}/gi, /\b[0-9a-f]{40,}\b/gi,
];
/** One log line: single-line, trimmed, secrets masked. */
export function scrubLine(s: unknown, max = 220): string {
  let t = String(s ?? "").replace(/[\r\n]+/g, " ").replace(/\s+/g, " ").trim();
  for (const re of SECRET) t = t.replace(re, "[hidden]");
  return t.length > max ? `${t.slice(0, max - 1)}…` : t;
}

export type BuildFacts = {
  buildId: string; status: string; errorCode: string | null; error: string | null; errorDetail: string | null; mcVersion: string | null; name: string | null;
  model: string | null; at: string | null; flightVerdict: string | null; flightFailed: string[]; events: { at?: string; text: string }[];
  prompt?: string | null; changeRequest?: string | null;
};

/** The ticket subject + body. The body starts with a machine-readable block support can grep. */
export function composeReport(input: ReportInput, facts: BuildFacts | null, who: { cyrusHost: boolean }): { subject: string; body: string } {
  const first = scrubLine(input.what.split("\n")[0], 70);
  const subject = `[Cyrus beta] ${REPORT_LABEL[input.category]}: ${first}`.slice(0, 150);
  const lines: string[] = [input.what, "", "---", "Sent from inside Cyrus (private beta)", `Type: ${REPORT_LABEL[input.category]}`, `Host: ${who.cyrusHost ? "cyrus.my" : "nxeon.cloud"}`];
  if (input.page) lines.push(`Page: ${input.page}`);
  if (facts) {
    lines.push(`Build: ${facts.buildId}${facts.name ? ` (${scrubLine(facts.name, 60)})` : ""}`, `Status: ${facts.status}${facts.errorCode ? ` / ${facts.errorCode}` : ""}`, `Minecraft: ${facts.mcVersion ?? "-"}   Model: ${facts.model ?? "-"}`);
    if (facts.flightVerdict) lines.push(`Test Flight: ${facts.flightVerdict}${facts.flightFailed.length ? ` (failed: ${facts.flightFailed.slice(0, 8).join(", ")})` : ""}`);
    if (input.includeLogs) {
      if (facts.error) lines.push(`Error shown to the user: ${scrubLine(facts.error, 300)}`);
      if (facts.errorDetail) lines.push(`Error detail: ${scrubLine(facts.errorDetail, 600)}`);
      if (facts.events.length) { lines.push("Last build events:"); for (const e of facts.events.slice(-20)) lines.push(`  ${e.at ? e.at.slice(11, 19) + " " : ""}${scrubLine(e.text)}`); }
    }
    if (input.includePrompt && facts.prompt) {
      lines.push("", "Prompt (included because the user ticked the box):", scrubLine(facts.prompt, 1500));
      if (facts.changeRequest) lines.push("Change request:", scrubLine(facts.changeRequest, 800));
    }
  } else if (input.buildId) lines.push(`Build: ${input.buildId} (not found on this account)`);
  return { subject, body: lines.join("\n").slice(0, 9500) };
}
