"use client";
// "Report a problem" (private beta): a small fixed button on every Cyrus screen. Sends the note, the build the person is
// looking at (taken from the URL) and, unless they untick it, that build's error and last events to /api/cyrus/report,
// which files a Nxeon support ticket labelled [Cyrus beta]. The prompt is sent only if the box is ticked.
import { useState } from "react";
import { usePathname } from "next/navigation";

const CATS: [string, string][] = [["bug", "Something broke or errored"], ["wrong", "The result was wrong"], ["slow", "It was slow or stuck"], ["billing", "Tokens or billing"], ["idea", "An idea or request"], ["other", "Something else"]];
const BUILD_RE = /\/(?:studio|dashboard\/cyrus)\/(?:projects\/)?([A-Za-z0-9_-]{8,64})(?:\/|$)/;

export function ReportProblem() {
  const path = usePathname() || "";
  const m = BUILD_RE.exec(path);
  const buildId = m && !["app", "packs", "import", "notifications"].includes(m[1]) ? m[1] : null;
  const [open, setOpen] = useState(false);
  const [what, setWhat] = useState("");
  const [category, setCategory] = useState("bug");
  const [logs, setLogs] = useState(true);
  const [prompt, setPrompt] = useState(false);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [done, setDone] = useState<string | null>(null);

  async function send(e: React.FormEvent) {
    e.preventDefault();
    if (busy) return;
    setBusy(true); setErr(null);
    try {
      const r = await fetch("/api/cyrus/report", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ what, category, buildId, includeLogs: logs, includePrompt: prompt, page: path.slice(0, 200) }) });
      const j = (await r.json()) as { ok?: boolean; url?: string; error?: string };
      if (j.ok && j.url) setDone(j.url); else setErr(j.error ?? "Could not send that.");
    } catch { setErr("Could not reach us. Try again."); }
    setBusy(false);
  }

  return (
    <>
      <button type="button" onClick={() => setOpen(true)} data-testid="report-problem" aria-label="Report a problem" title="Report a problem"
        className="fixed bottom-3 left-3 z-40 inline-flex h-8 items-center gap-1.5 rounded-full border border-white/15 bg-black/60 px-3 text-[12px] font-semibold text-white/80 backdrop-blur hover:text-white max-sm:bottom-16">
        <span aria-hidden>!</span><span className="hidden sm:inline">Report a problem</span>
      </button>
      {open ? (
        <div className="fixed inset-0 z-[90] grid place-items-center bg-black/60 p-4" role="dialog" aria-modal="true" aria-labelledby="rp-h" onMouseDown={(e) => e.target === e.currentTarget && setOpen(false)}>
          <form onSubmit={send} className="w-full max-w-[460px] rounded-[16px] border border-white/15 bg-[#0b0d16] p-5 text-white">
            <h2 id="rp-h" className="text-[17px] font-semibold">Report a problem</h2>
            {done ? (
              <div className="mt-3 space-y-3 text-[13px]">
                <p className="text-emerald-300" role="status">Sent. We have the details{buildId ? " of this build" : ""}.</p>
                <p className="text-white/70">You can follow it here: <a className="underline" href={done} target="_blank" rel="noopener noreferrer">your support ticket</a>.</p>
                <button type="button" onClick={() => { setOpen(false); setDone(null); setWhat(""); }} className="rounded-[10px] bg-white px-4 py-2 text-[13px] font-semibold text-black">Close</button>
              </div>
            ) : (
              <>
                <p className="mt-1 text-[12.5px] text-white/60">{buildId ? "We attach this build's error and last events so you do not have to copy anything." : "Open a build first if it is about one, so we can attach its details."}</p>
                <label className="mt-3 block text-[12px] font-semibold text-white/70" htmlFor="rp-cat">What kind of problem</label>
                <select id="rp-cat" value={category} onChange={(e) => setCategory(e.target.value)} className="mt-1 w-full rounded-[10px] border border-white/20 bg-black/40 px-3 py-2 text-[14px]">
                  {CATS.map(([v, l]) => <option key={v} value={v}>{l}</option>)}
                </select>
                <label className="mt-3 block text-[12px] font-semibold text-white/70" htmlFor="rp-what">What happened</label>
                <textarea id="rp-what" required minLength={5} maxLength={4000} rows={5} value={what} onChange={(e) => setWhat(e.target.value)} placeholder="What did you try, what did you expect, what happened instead?" className="mt-1 w-full rounded-[10px] border border-white/20 bg-black/40 px-3 py-2 text-[14px]" />
                {buildId ? (
                  <div className="mt-2 space-y-1 text-[12.5px] text-white/75">
                    <label className="flex items-center gap-2"><input type="checkbox" checked={logs} onChange={(e) => setLogs(e.target.checked)} /> Include this build&apos;s error and last events</label>
                    <label className="flex items-center gap-2"><input type="checkbox" checked={prompt} onChange={(e) => setPrompt(e.target.checked)} /> Include my prompt text</label>
                  </div>
                ) : null}
                {err ? <p className="mt-2 text-[12.5px] text-red-300" role="alert">{err}</p> : null}
                <div className="mt-4 flex gap-2">
                  <button type="submit" disabled={busy || what.trim().length < 5} className="rounded-[10px] bg-white px-4 py-2 text-[13px] font-semibold text-black disabled:opacity-40">{busy ? "Sending..." : "Send"}</button>
                  <button type="button" onClick={() => setOpen(false)} className="rounded-[10px] border border-white/20 px-4 py-2 text-[13px]">Cancel</button>
                </div>
              </>
            )}
          </form>
        </div>
      ) : null}
    </>
  );
}
