#!/usr/bin/env node
// Cyrus DAILY BETA HEALTH REPORT for the owner. READ ONLY (psql in a read-only transaction, file reads). Prints markdown;
// no prompt text, no emails, no secrets. Run it by hand or from a timer; --discord posts the short form to the alert webhook.
//   node scripts/cyrus/beta-report.mjs [--hours 24] [--json FILE] [--discord]
//   node scripts/cyrus/beta-report.mjs --hours 168        # the week
// Needs DATABASE_URL (read from /opt/nxeon/.env like launch-check, or CYRUS_DATABASE_URL). Tables that do not exist yet
// (CyrusGuardRefusal before the migration) are reported as "not available", never as zero.
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";

const args = process.argv.slice(2);
const opt = (n, d) => { const i = args.indexOf(n); return i >= 0 && args[i + 1] ? args[i + 1] : d; };
const hours = Math.max(1, Math.min(24 * 90, Number(opt("--hours", "24")) || 24));
const E = process.env;

function envFile(p) {
  const out = {};
  try { for (const l of readFileSync(p, "utf8").split("\n")) { const m = /^([A-Z0-9_]+)=(.*)$/.exec(l.trim()); if (m) out[m[1]] = m[2].replace(/^["']|["']$/g, ""); } } catch { /* none */ }
  return out;
}
const fileEnv = envFile(E.ENVF || "/opt/nxeon/.env");
const dbUrl = (E.CYRUS_DATABASE_URL || fileEnv.CYRUS_DATABASE_URL || E.DATABASE_URL || fileEnv.DATABASE_URL || "")
  .replace(/([?&])(connection_limit|pool_timeout|schema|pgbouncer|socket_timeout|statement_cache_size)=[^&]*/g, "$1").replace(/&&+/g, "&").replace("?&", "?").replace(/[?&]+$/, "");
if (!dbUrl) { console.error("no DATABASE_URL (set ENVF or DATABASE_URL)"); process.exit(2); }

/** One read-only query -> rows of arrays (tab separated). null = the query failed (table missing etc.). */
function q(sql) {
  try {
    const out = execFileSync("psql", [dbUrl, "-XAtq", "-F", "\t", "-v", "ON_ERROR_STOP=1", "-c", sql], { encoding: "utf8", timeout: 30000, env: { ...process.env, PGOPTIONS: "-c default_transaction_read_only=on" }, stdio: ["ignore", "pipe", "pipe"] }).trim();
    return out ? out.split("\n").map((l) => l.split("\t")) : [];
  } catch { return null; }
}
const num = (v) => (v === undefined || v === null || v === "" ? 0 : Number(v));
const usd = (v) => `$${num(v).toFixed(2)}`;
const pct = (a, b) => (b ? `${Math.round((a / b) * 1000) / 10}%` : "n/a");
const W = `now() - interval '${hours} hours'`;

const R = { hours, at: new Date().toISOString() };

// builds
const b = q(`select count(*), count(*) filter (where status='succeeded'), count(*) filter (where status='failed' and "errorCode" is distinct from 'refused' and "errorCode" is distinct from 'cancelled' and "errorCode" is distinct from 'admin_cancelled'),
  count(*) filter (where "errorCode"='refused'), count(*) filter (where "errorCode" in ('cancelled','admin_cancelled')), count(*) filter (where status not in ('succeeded','failed')),
  count(*) filter (where status='succeeded' and attempts=1), coalesce(sum("costUsd"),0), coalesce(sum("costUsd") filter (where status='succeeded'),0),
  coalesce(percentile_cont(0.5) within group (order by "durationMs") filter (where status='succeeded'),0)/1000, coalesce(percentile_cont(0.9) within group (order by "durationMs") filter (where status='succeeded'),0)/1000,
  count(distinct "userId") from "ModBuild" where "createdAt" > ${W}`);
if (b?.[0]) {
  const [total, ok, failed, refused, cancelled, running, first, cost, costOk, p50, p90, users] = b[0].map(Number);
  R.builds = { total, succeeded: ok, failed, refused, cancelled, running, firstTry: first, costUsd: cost, costPerSuccessUsd: ok ? costOk / ok : null, p50s: Math.round(p50), p90s: Math.round(p90), activeUsers: users };
}
const codes = q(`select coalesce("errorCode",'(none)'), count(*), coalesce(sum("costUsd"),0) from "ModBuild" where status='failed' and "createdAt" > ${W} group by 1 order by 2 desc limit 8`);
R.failuresByCode = codes?.map(([c, n, s]) => ({ code: c, n: num(n), costUsd: num(s) })) ?? null;
const flight = q(`select coalesce(cyrus->'testFlight'->>'verdict','none'), count(*) from "ModBuild" where status='succeeded' and "createdAt" > ${W} group by 1`);
R.flight = flight ? Object.fromEntries(flight.map(([k, n]) => [k, num(n)])) : null;
const model = q(`select coalesce(model,'?'), count(*), count(*) filter (where status='succeeded') from "ModBuild" where "createdAt" > ${W} group by 1 order by 2 desc`);
R.byModel = model?.map(([m, n, s]) => ({ model: m, n: num(n), succeeded: num(s) })) ?? null;

// tokens (ledger deltas; spend rows are negative)
const t = q(`select coalesce(sum(delta) filter (where kind='spend'),0), coalesce(sum(delta) filter (where kind in ('grant','purchase')),0), coalesce(sum(delta) filter (where kind='release'),0), count(*) filter (where kind='revoke') from "CyrusTokenLedger" where "createdAt" > ${W}`);
if (t?.[0]) R.tokens = { spent: -num(t[0][0]), granted: num(t[0][1]), released: num(t[0][2]), revokes: num(t[0][3]) };
const acc = q(`select count(*), coalesce(sum(balance),0), coalesce(sum(reserved),0), count(*) filter (where balance < 0) from "CyrusTokenAccount"`);
