  refused: g.reduce((s, r) => s + num(r[2]), 0),
  falsePositive: g.filter((r) => r[1] === "false_positive").reduce((s, r) => s + num(r[2]), 0),
  correct: g.filter((r) => r[1] === "correct").reduce((s, r) => s + num(r[2]), 0),
  open: g.filter((r) => r[1] === "new").reduce((s, r) => s + num(r[2]), 0),
  byClass: g.reduce((m, r) => ((m[r[0]] = (m[r[0]] || 0) + num(r[2])), m), {}),
};
const gOpen = q(`select count(*), coalesce(min(extract(epoch from now()-"createdAt")/86400),0) from "CyrusGuardRefusal" where status='new'`);
R.guardOpenTotal = gOpen?.[0] ? { n: num(gOpen[0][0]) } : null;

// people
const cr = q(`select count(*) filter (where "usernameKey" is not null), count(*) filter (where "termsVersion" is not null), count(*) from "CyrusCreator"`);
R.welcome = cr?.[0] ? { usernames: num(cr[0][0]), termsAccepted: num(cr[0][1]), creators: num(cr[0][2]) } : null;
const allow = q(`select value from "Setting" where key='preview_access_emails_modbuilder'`);
R.invited = allow?.[0] ? (allow[0][0] || "").split(/[,\s;]+/).filter((e) => e.includes("@")).length : null;

// support + errors
const tk = q(`select count(*), count(*) filter (where status='OPEN') from "Ticket" where subject like '[Cyrus%' and "createdAt" > ${W}`);
R.reports = tk?.[0] ? { filed: num(tk[0][0]), open: num(tk[0][1]) } : null;
const el = q(`select left(coalesce(source,'?'),20), left(coalesce(context,message,''),70), count from "ErrorLog" where "lastSeen" > ${W} and level='error' and (coalesce(context,'') ilike '%cyrus%' or coalesce(message,'') ilike '%cyrus%' or coalesce(source,'') ilike '%cyrus%' or coalesce(source,'') ilike '%modbuild%') order by count desc limit 5`);
