if (R.staleReservations) flags.push(`${R.staleReservations} reservation(s) held over 2 h`);
if (R.alertsFiring?.length) flags.push(`alerts firing: ${R.alertsFiring.join(", ")}`);
if (R.guard === null) flags.push("guard refusal log not available (apply the 2026-10-15 migration)");
