const E = process.env;

function envFile(p) {
  const out = {};
  try { for (const l of readFileSync(p, "utf8").split("\n")) { const m = /^([A-Z0-9_]+)=(.*)$/.exec(l.trim()); if (m) out[m[1]] = m[2].replace(/^["']|["']$/g, ""); } } catch { /* none */ }
  return out;
}
const fileEnv = envFile(E.ENVF || "/opt/nxeon/.env");
const dbUrl = (E.CYRUS_DATABASE_URL || fileEnv.CYRUS_DATABASE_URL || E.DATABASE_URL || fileEnv.DATABASE_URL || "")
  .replace(/([?&])(connection_limit|pool_timeout|schema|pgbouncer|socket_timeout|statement_cache_size)=[^&]*/g, "$1").replace(/&&+/g, "&").replace("?&", "?").replace(/[?&]+$/, "");
