    const out = execFileSync("psql", [dbUrl, "-XAtq", "-F", "\t", "-v", "ON_ERROR_STOP=1", "-c", sql], { encoding: "utf8", timeout: 30000, env: { ...process.env, PGOPTIONS: "-c default_transaction_read_only=on" }, stdio: ["ignore", "pipe", "pipe"] }).trim();
    return out ? out.split("\n").map((l) => l.split("\t")) : [];
