#!/usr/bin/env node
// Cyrus private-beta allow-list from the command line (the admin tab Admin > Cyrus > Beta invites does the same).
//   node scripts/cyrus/beta-invites.mjs list
//   node scripts/cyrus/beta-invites.mjs add  a@x.com b@y.com ...            # dry run: shows the new list
//   node scripts/cyrus/beta-invites.mjs add  a@x.com --apply                 # writes the Setting (PRODUCTION WRITE: owner only)
//   node scripts/cyrus/beta-invites.mjs add  --file invitees.txt --apply
//   node scripts/cyrus/beta-invites.mjs remove a@x.com --apply
//   node scripts/cyrus/beta-invites.mjs check a@x.com                        # is this email on the list? has an account? finished Welcome?
// The list is the Setting `preview_access_emails_modbuilder`. An account may use Cyrus while its VERIFIED email is on it.
// Nothing is written without --apply; every write first saves the previous value to <state dir>/beta-invites-<UTC>.bak.
// This tool sends no email (use the admin tab for the one-time invite, or write to people yourself).
import { execFileSync } from "node:child_process";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";

const KEY = "preview_access_emails_modbuilder";
const MAX = 200;
const EMAIL = /^[^\s@<>"',;]{1,64}@[^\s@<>"',;]{1,253}\.[A-Za-z]{2,24}$/;
const args = process.argv.slice(2);
const cmd = args[0];
const apply = args.includes("--apply");
const fileIdx = args.indexOf("--file");
const words = args.slice(1).filter((a, i, arr) => !a.startsWith("--") && arr[i - 1] !== "--file");
if (!["list", "add", "remove", "check"].includes(cmd)) { console.error("usage: beta-invites.mjs list | add EMAIL... [--file F] [--apply] | remove EMAIL... [--apply] | check EMAIL"); process.exit(2); }

const env = {};
try { for (const l of readFileSync(process.env.ENVF || "/opt/nxeon/.env", "utf8").split("\n")) { const m = /^([A-Z0-9_]+)=(.*)$/.exec(l.trim()); if (m) env[m[1]] = m[2].replace(/^["']|["']$/g, ""); } } catch { /* use process env */ }
const url = (process.env.DATABASE_URL || env.DATABASE_URL || "").replace(/([?&])(connection_limit|pool_timeout|schema|pgbouncer|socket_timeout|statement_cache_size)=[^&]*/g, "$1").replace(/&&+/g, "&").replace("?&", "?").replace(/[?&]+$/, "");
if (!url) { console.error("no DATABASE_URL"); process.exit(2); }
const psql = (sql, ro = true) => execFileSync("psql", [url, "-XAtq", "-v", "ON_ERROR_STOP=1", "-c", sql], { encoding: "utf8", timeout: 20000, env: { ...process.env, ...(ro ? { PGOPTIONS: "-c default_transaction_read_only=on" } : {}) } }).trim();
const parse = (raw) => [...new Set((raw || "").split(/[,\s;]+/).map((e) => e.trim().toLowerCase()).filter((e) => EMAIL.test(e)))];
const lit = (s) => `'${s.replace(/'/g, "''")}'`;

const cur = parse(psql(`select value from "Setting" where key = ${lit(KEY)}`));
const input = [...words, ...(fileIdx >= 0 ? readFileSync(args[fileIdx + 1], "utf8").split(/[\s,;]+/) : [])].map((e) => e.trim().toLowerCase()).filter(Boolean);

if (cmd === "list") { console.log(`${cur.length} on the allow-list (${KEY})`); for (const e of cur) console.log(`  ${e}`); process.exit(0); }
if (cmd === "check") {
  for (const e of input) {
    const rows = psql(`select u.id, (u."emailVerifiedAt" is not null), c."usernameKey" is not null, c."termsVersion" from "User" u left join "CyrusCreator" c on c."userId" = u.id where lower(u.email) = ${lit(e)}`);
    const [id, verified, hasName, terms] = rows ? rows.split("|") : [];
    console.log(`${e}: ${cur.includes(e) ? "ON the list" : "NOT on the list"}; ${id ? `account exists, email ${verified === "t" ? "verified" : "NOT verified"}, username ${hasName === "t" ? "chosen" : "not chosen yet"}, Terms ${terms ? "v" + terms : "not accepted"}` : "no account yet (they sign up on cyrus.my with this address)"}`);
  }
  process.exit(0);
}

const bad = input.filter((e) => !EMAIL.test(e));
if (bad.length) console.error(`ignoring ${bad.length} value(s) that are not email addresses: ${bad.slice(0, 5).join(", ")}`);
const good = input.filter((e) => EMAIL.test(e));
let next = [...cur];
if (cmd === "add") { for (const e of good) if (!next.includes(e) && next.length < MAX) next.push(e); }
else next = next.filter((e) => !good.includes(e));
const added = next.filter((e) => !cur.includes(e)), removed = cur.filter((e) => !next.includes(e));
console.log(`${cur.length} -> ${next.length} on the list; +${added.length} -${removed.length}`);
for (const e of added) console.log(`  + ${e}`);
for (const e of removed) console.log(`  - ${e}`);
if (!added.length && !removed.length) process.exit(0);
if (next.length === 0) { console.error("refusing to write an EMPTY list (an empty value means nobody, the owner included)"); process.exit(3); }
if (!apply) { console.log("\nDRY RUN: nothing written. Re-run with --apply to write the Setting."); process.exit(0); }

const dir = process.env.CYRUS_STATE_DIR || "/var/lib/cyrus";
const stamp = new Date().toISOString().replace(/[-:]/g, "").slice(0, 15) + "Z";
try { mkdirSync(dir, { recursive: true }); writeFileSync(`${dir}/beta-invites-${stamp}.bak`, cur.join(",") + "\n"); console.log(`previous list saved to ${dir}/beta-invites-${stamp}.bak`); } catch (e) { console.error(`could not save a backup (${e.message}); not writing`); process.exit(4); }
psql(`insert into "Setting"(key, value) values (${lit(KEY)}, ${lit(next.join(","))}) on conflict (key) do update set value = excluded.value`, false);
console.log("written. Effective on the next request (no restart).");
EOF
node scripts/cyrus/beta-invites.mjs add test1@example.com | tail -4; node scripts/cyrus/beta-invites.mjs list | head -2 | sed -E 's/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+/<email>/g'

