import { CYRUS_LEGAL } from "../lib/legal/cyrus";

const ROOT = path.join(__dirname, "..");
const src = (p: string) => readFileSync(path.join(ROOT, p), "utf8");

describe("terms version rules", () => {
  it("major version decides", () => {
    assert.equal(termsMajor("1.0"), "1");
    assert.equal(termsMajor("12.4.1"), "12");
    assert.equal(termsMajor(""), null);
    assert.equal(termsMajor("v1"), null);
    assert.equal(termsCovered("1.0", "1.3"), true, "a minor edit never interrupts anybody");
    assert.equal(termsCovered("1.9", "2.0"), false, "a new major asks again");
    assert.equal(termsCovered(null, "1.0"), false);
    assert.equal(termsCovered("garbage", "1.0"), false);
  });
  it("needs: username first, then terms; empty when both done", () => {
    assert.deepEqual(onboardingNeeds({ usernameKey: null, termsVersion: null, currentTerms: "1.0" }), ["username", "terms"]);
    assert.deepEqual(onboardingNeeds({ usernameKey: "maker", termsVersion: null, currentTerms: "1.0" }), ["terms"]);
    assert.deepEqual(onboardingNeeds({ usernameKey: null, termsVersion: "1.0", currentTerms: "1.0" }), ["username"]);
    assert.deepEqual(onboardingNeeds({ usernameKey: "maker", termsVersion: "1.0", currentTerms: "1.4" }), []);
  });
  it("the current CYRUS_LEGAL.version is a parseable major.minor", () => assert.ok(termsMajor(CYRUS_LEGAL.version)));
});

describe("welcome submission", () => {
  const cur = "1.0";
  it("needs a username when the account has none", () => {
    const r = checkWelcomeInput(["username", "terms"], { acceptTerms: true, termsVersion: cur }, cur);
    assert.equal(r.ok, false);
    if (!r.ok) assert.equal(r.code, "username_required");
  });
  it("needs the box ticked when terms are owed", () => {
    const r = checkWelcomeInput(["username", "terms"], { username: "maker_1", termsVersion: cur }, cur);
    assert.ok(!r.ok && r.code === "terms_required");
  });
  it("refuses a stale terms version (never accept text the person was not shown)", () => {
    const r = checkWelcomeInput(["terms"], { acceptTerms: true, termsVersion: "0.9" }, cur);
    assert.ok(!r.ok && r.code === "terms_changed");
  });
  it("accepts a complete answer; terms-only needs no username", () => {
    assert.deepEqual(checkWelcomeInput(["username", "terms"], { username: "maker_1", acceptTerms: true, termsVersion: cur }, cur), { ok: true, wantsUsername: true });
    assert.deepEqual(checkWelcomeInput(["terms"], { acceptTerms: true, termsVersion: cur }, cur), { ok: true, wantsUsername: false });
  });
  it("legal links follow the host", () => {
    assert.equal(legalLinks(true).terms, "/legal/terms");
    assert.equal(legalLinks(false).privacy, "/legal/cyrus-privacy");
  });
});

describe("every entry point leads to the step, none to a dead end", () => {
  it("the access rule requires the whole step, fails closed, and exposes the reason", () => {
    const a = src("lib/modbuilder/access.ts");
    assert.match(a, /onboardingComplete\(user\.id\)\.catch\(\(\) => false\)/);
    assert.match(a, /export async function modBuilderAccessState/);
    assert.match(a, /export async function modBuilderUserPendingUsername/);
  });
  it("sign-in callbacks and the sign-in page send a pending account on (not to the private-beta panel)", () => {
    for (const f of ["app/cyrus-host/auth/callback/route.ts", "app/cyrus-host/auth/google/callback/route.ts", "app/cyrus-host/sign-in/SignInView.tsx"]) {
      const s = src(f);
      assert.match(s, /modBuilderAccessState/, f);
      assert.doesNotMatch(s, /modBuilderAccess\(|modBuilderUser\(\)/, `${f} must not use the strict rule for the beta-panel decision`);
    }
  });
  it("the portal top bar and server page show Cyrus to a pending account", () => {
    assert.match(src("app/dashboard/layout.tsx"), /modBuilderUserPendingUsername/);
    assert.match(src("app/dashboard/servers/[id]/page.tsx"), /modBuilderUserPendingUsername/);
  });
  it("the layout gate gets needs, version and host-aware legal links; there is no auto-reload loop in the component", () => {
    const l = src("app/dashboard/cyrus/layout.tsx");
    assert.match(l, /onboardingStateFor/);
    assert.match(l, /legalLinks\(onCyrusHost\)/);
    const c = src("components/cyrus/username/UsernameGate.tsx");
    assert.match(c, /data-testid="accept-terms"/);
    assert.doesNotMatch(c, /location\.reload|window\.location/);
  });
  it("API clients get a typed onboarding_required with the URL", () => {
    assert.match(src("lib/cyrus/api/v1/http.ts"), /personal\.refusal/);
    assert.match(src("lib/cyrus/host/nxeon.ts"), /onboarding_required/);
    assert.match(src("lib/cyrus/api/v1/writes.ts"), /writes\.refusal/);
  });
  it("the POST route records terms with the username in one write and rejects a stale version", () => {
    const r = src("app/api/cyrus/username/route.ts");
    assert.match(r, /checkWelcomeInput/);
    assert.match(r, /setUsername\(user\.id, b\.username, \{ acceptTerms: accept \}\)/);
    assert.match(src("lib/cyrus-mods/username-store.ts"), /\.\.\.terms/);
  });
  it("the migration carries every column and table the code reads", () => {
    const sql = src("prisma/manual-migrations/2026-10-15-cyrus-welcome-and-guard.sql");
    for (const w of ['"termsVersion"', '"termsAcceptedAt"', '"usernameKey"', "CyrusUsernameHold", "CyrusGuardRefusal", "IF NOT EXISTS"]) assert.ok(sql.includes(w), w);
    const schema = src("prisma/schema.prisma");
    assert.match(schema, /termsVersion\s+String\?/);
    assert.match(schema, /model CyrusGuardRefusal/);
  });
});
