// Private-beta operations pack (2026-10-15): invites, "report a problem", guard-refusal log + replay, Stripe tags, alert rules,
// launch-check additions, billing fixes found by the launch audit. Pure rules + source/data pins.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { execFileSync, spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import path from "node:path";
import { addEmails, parseInviteLog, parseList, removeEmail, renderInvite, MAX_LIST } from "../lib/cyrus/beta/invites";
import { composeReport, parseReport, scrubLine } from "../lib/cyrus/support/report";
import { GUARD_TEXT_RETENTION_DAYS, normalizePrompt, promptHash, refusalClassOf, refusalRow } from "../lib/cyrus/guard/refusal-rules";
import { CYRUS_PRODUCT_TAG, CYRUS_STATEMENT_SUFFIX, validDescriptor, withProductTag } from "../lib/cyrus/tokens/stripe-tags";

const ROOT = path.join(__dirname, "..");
const src = (p: string) => readFileSync(path.join(ROOT, p), "utf8");

describe("beta allow-list", () => {
  it("parses any separator, lowercases, dedupes, drops junk", () => {
    assert.deepEqual(parseList("A@x.com, b@y.org;A@X.com\nnot-an-email  c@z.io"), ["a@x.com", "b@y.org", "c@z.io"]);
  });
  it("add reports added / already / invalid and never removes", () => {
    const r = addEmails(["a@x.com"], "a@x.com new@y.org bad@@");
    assert.deepEqual([r.added, r.already, r.invalid.length, r.next], [["new@y.org"], ["a@x.com"], 1, ["a@x.com", "new@y.org"]]);
  });
  it("caps the list", () => {
    const cur = Array.from({ length: MAX_LIST }, (_, i) => `u${i}@x.com`);
    const r = addEmails(cur, "extra@x.com");
    assert.deepEqual([r.added.length, r.full], [0, ["extra@x.com"]]);
  });
  it("remove is exact and case-insensitive", () => {
    assert.deepEqual(removeEmail(["a@x.com", "b@x.com"], " B@X.com "), { next: ["a@x.com"], removed: true });
    assert.equal(removeEmail(["a@x.com"], "zz@x.com").removed, false);
  });
  it("the invite log ignores garbage", () => {
    assert.deepEqual(parseInviteLog('{"a@x.com":{"at":"2026-10-15T10:00:00Z","wave":"W0"},"bad":1,"nope":{"at":5}}'), { "a@x.com": { at: "2026-10-15T10:00:00Z", wave: "W0" } });
    assert.deepEqual(parseInviteLog("not json"), {});
  });
});

describe("invite email", () => {
  const m = renderInvite({ email: "friend@example.com", cyrusOrigin: "https://cyrus.my", assetBase: "https://nxeon.cloud", wave: "W0", note: "Glad to have you <b>&" });
  it("is a one-time personal message: no unsubscribe machinery, says why, how to stop", () => {
    assert.doesNotMatch(m.html, /List-Unsubscribe|unsubscribe/i);
    assert.match(m.html, /one-time invitation/);
    assert.match(m.text, /Reply "stop"/);
  });
  it("tells the person which address to sign in with and links to cyrus.my", () => {
    assert.match(m.text, /friend@example\.com/);
    assert.match(m.html, /https:\/\/cyrus\.my\/sign-in\?next=%2Fstudio/);
  });
  it("escapes the note", () => {
    assert.doesNotMatch(m.html, /<b>&(?!amp;)/);
    assert.match(m.html, /&lt;b&gt;/);
  });
  it("the admin action sends only through the cyrus.my sender, once per address", () => {
    const a = src("lib/actions-cyrus-admin.ts");
    const body = a.slice(a.indexOf("export async function adminCyrusBetaAdd"), a.indexOf("export async function adminCyrusBetaRemove"));
    assert.match(body, /validCyrusSender\(from\)/);
    assert.match(body, /if \(log\[e\]\) \{ skipped\+\+; continue; \}/);
    assert.match(body, /guard\("beta\.list"\)/);
    assert.match(body, /cyrusAudit\(/);
  });
});

describe("report a problem", () => {
  it("validates input", () => {
    assert.equal(parseReport({ what: "x" }).ok, false);
    assert.equal(parseReport({ what: "y".repeat(4001) }).ok, false);
    const ok = parseReport({ what: "The build failed twice", category: "wrong", buildId: "mb123abc", includePrompt: true, page: "/studio/mb123abc" });
    assert.ok(ok.ok);
    if (ok.ok) assert.deepEqual([ok.input.category, ok.input.buildId, ok.input.includePrompt, ok.input.includeLogs], ["wrong", "mb123abc", true, true]);
    const evil = parseReport({ what: "hello there", buildId: "../etc/passwd", page: "https://evil", category: "zzz" });
    assert.ok(evil.ok);
    if (evil.ok) assert.deepEqual([evil.input.buildId, evil.input.page, evil.input.category], [null, null, "bug"]);
  });
  it("scrubs secrets from log lines", () => {
    const s = scrubLine("token=abcd1234efgh and [REDACTED] and Bearer abcdefghijklmnop1234 ok");
    assert.doesNotMatch(s, /abcd1234efgh|sk-ant-api03|abcdefghijklmnop1234/);
  });
  const facts = { buildId: "mb1", status: "failed", errorCode: "compile", error: "javac failed", errorDetail: "x.java:3 error", mcVersion: "1.21.11", name: "Frost", model: "saka", at: null, flightVerdict: "failed", flightFailed: ["boot"], events: [{ text: "compiling" }], prompt: "SECRET PROMPT TEXT", changeRequest: null };
  const base = { what: "It did not compile", category: "bug" as const, buildId: "mb1", includeLogs: true, includePrompt: false, page: "/studio/mb1" };
  it("labels the ticket and keeps the prompt out unless asked", () => {
    const m = composeReport(base, facts, { cyrusHost: true });
    assert.match(m.subject, /^\[Cyrus beta\]/);
    assert.match(m.body, /Build: mb1 \(Frost\)/);
    assert.match(m.body, /Test Flight: failed \(failed: boot\)/);
    assert.doesNotMatch(m.body, /SECRET PROMPT TEXT/);
    assert.match(composeReport({ ...base, includePrompt: true }, facts, { cyrusHost: false }).body, /SECRET PROMPT TEXT/);
    assert.doesNotMatch(composeReport({ ...base, includeLogs: false }, facts, { cyrusHost: true }).body, /javac failed/);
  });
  it("the route is same-origin, rate limited, own-build only, files a Nxeon ticket and mirrors it", () => {
    const r = src("app/api/cyrus/report/route.ts");
    for (const w of ["origin !== new URL(req.url).origin", "checkRateLimit", "b.userId === user.id", "createTicketCore", "mirrorNewTicketToDiscord", "attachTicketContext"]) assert.ok(r.includes(w), w);
  });
});

describe("guard refusal log", () => {
  it("hash ignores case and whitespace", () => {
    assert.equal(promptHash("Make  a\nBoss"), promptHash("make a boss"));
    assert.equal(normalizePrompt("  A   B "), "a b");
  });
  it("class comes from guard:<class>, else other", () => {
    assert.equal(refusalClassOf("guard:escape"), "escape");
    assert.equal(refusalClassOf("blah"), "other");
    assert.equal(refusalClassOf(null), "other");
  });
  it("the row keeps the text only in promptText with a 30 day purge date", () => {
    const now = new Date("2026-10-15T00:00:00Z");
    const r = refusalRow({ id: "b1", userId: "u1", status: "failed", errorCode: "refused", prompt: "build a dungeon", changeRequest: "keep rooms", baseBuildId: "b0", result: { errorDetail: "guard:escape" } }, now);
    assert.equal(r.refusalClass, "escape");
    assert.equal(r.kind, "change");
    assert.equal(r.promptText, "build a dungeon\nkeep rooms");
    assert.equal(r.purgeAt.toISOString(), "2026-11-14T00:00:00.000Z");
    assert.equal(GUARD_TEXT_RETENTION_DAYS, 30);
    const others = JSON.stringify({ ...r, promptText: undefined });
    assert.doesNotMatch(others, /dungeon|keep rooms/);
  });
  it("is recorded from the build sync, purged by the worker, erased with the account, and surfaced in the Learning tab", () => {
    assert.match(src("lib/modbuilder/store.ts"), /recordGuardRefusal/);
    assert.match(src("lib/cyrus/worker/schedule.ts"), /purgeGuardRefusalText/);
    assert.match(src("lib/cyrus/admin/ops.ts"), /model: "cyrusGuardRefusal"/);
    assert.match(src("app/admin/cyrus/learning/page.tsx"), /adminCyrusGuardReview/);
  });
  it("learning mining never receives refused text from this log", () => {
    for (const f of ["lib/cyrus/learning/mining.ts", "lib/cyrus/learning/signals.ts", "lib/cyrus/learning/aggregate.ts"]) assert.doesNotMatch(src(f), /cyrusGuardRefusal|promptText/, f);
  });
});

describe("guard replay (offline screen)", () => {
  it("runs, finds no unsafe prompt excused, keeps every refusal clause", () => {
    const out = execFileSync("node", ["scripts/cyrus/guard-replay.mjs", "--json", "/dev/null"], { cwd: ROOT, encoding: "utf8" });
    assert.match(out, /OK: no candidate clause matches any prompt in the unsafe set/);
    assert.match(out, /fp-dungeon-escape \[recorded\].*v2-worlds-and-state/);
    assert.match(out, /refusal clauses kept=true, sits in the NOT-refusals list=true/);
  });
  it("the rejected candidate stays rejected (it would excuse the hidden-op prompt)", () => {
    const c = JSON.parse(src("services/modbuilder/eval/guard-candidates.json"));
    assert.ok(c.rejected["v2-console-commands"]);
    assert.equal(c.candidates["v2-console-commands"], undefined);
  });
  it("the live GUARD_PROMPT is untouched by this pass (a prompt change needs the eval gate and an image)", () => {
    const r = src("services/modbuilder/route.js");
    assert.doesNotMatch(r, /in-game worlds, dimensions, arenas or islands/);
  });
  it("refuses the model judge without --yes-spend", () => {
    const r = spawnSync("node", ["scripts/cyrus/guard-replay.mjs", "--judge", "claude"], { cwd: ROOT, encoding: "utf8" });
    assert.equal(r.status, 2);
  });
});

describe("Stripe: shared account tags and launch-audit fixes", () => {
  it("product tag is first-class and cannot be overridden", () => {
    assert.equal(withProductTag({ product: "other", cyrusKind: "topup" } as Record<string, string>).product, CYRUS_PRODUCT_TAG);
    assert.ok(validDescriptor(CYRUS_STATEMENT_SUFFIX));
    assert.equal(validDescriptor("NO*PE"), false);
  });
  it("every Cyrus checkout is tagged and the top-up shows CYRUS on the statement", () => {
    const b = src("lib/cyrus/tokens/billing.ts");
    assert.equal((b.match(/withProductTag\(/g) ?? []).length >= 3, true);
    assert.match(b, /statement_descriptor_suffix: CYRUS_STATEMENT_SUFFIX/);
    assert.match(src("lib/cyrus/storage/addon.ts"), /withProductTag\(\{ cyrusUserId/);
    const setup = src("scripts/cyrus-tokens-stripe-setup.ts");
    assert.match(setup, /statement_descriptor: CYRUS_PRODUCT_DESCRIPTOR/);
    assert.match(setup, /product: "cyrus"/);
  });
  it("a storage add-on subscription is never mirrored as a plan (finding H1)", () => {
    const b = src("lib/cyrus/tokens/billing.ts");
    assert.match(b, /cyrusKind === "storage"\) return null;/);
    assert.match(b, /md\?\.cyrusKind === "storage"\) return null;/);
    assert.match(b, /obj\.metadata\.cyrusKind === "storage"\) return false;/);
  });
  it("card top-up recovery runs without CYRUS_PURCHASE_EVENTS (finding H2)", () => {
    assert.doesNotMatch(src("lib/cyrus/tokens/purchase.ts").slice(src("lib/cyrus/tokens/purchase.ts").indexOf("export async function reconcileCardTopups")), /^[\s\S]{0,400}if \(!purchaseEventsEnabled\(\)\) return/);
    assert.doesNotMatch(src("lib/cyrus/tokens/sweep.ts"), /process\.env\.CYRUS_PURCHASE_EVENTS === "1" && now/);
  });
