// Regenerate docs/api/cyrus-v1.openapi.yaml from lib/cyrus/api/v1 (Zod schemas + the operation table).
//   npx tsx tools/cyrus-api/gen-openapi.ts          write the file
//   npx tsx tools/cyrus-api/gen-openapi.ts --check  exit 1 when the file is out of date
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { openApiYaml } from "../../lib/cyrus/api/v1/contract-file";

const FILE = path.resolve(__dirname, "..", "..", "docs", "api", "cyrus-v1.openapi.yaml");
const want = openApiYaml();
if (process.argv.includes("--check")) {
  let have = "";
  try { have = readFileSync(FILE, "utf8"); } catch { /* missing */ }
  if (have !== want) { console.error(`${path.relative(process.cwd(), FILE)} is out of date: run npx tsx tools/cyrus-api/gen-openapi.ts`); process.exit(1); }
  console.log("openapi file up to date");
} else {
  writeFileSync(FILE, want);
  console.log(`wrote ${FILE} (${want.length} bytes)`);
}
